mapper.select:
SELECT id, idempotent_key, biz_type, user_id, request_fingerprint, biz_id, status, expire_time, create_time
FROM idempotent_record
WHERE idempotent_key = #{idempotentKey}

mapper.update:
UPDATE idempotent_record
SET request_fingerprint = #{requestFingerprint}
WHERE idempotent_key = #{idempotentKey}
  AND user_id = #{userId}
  AND status = 0
  AND request_fingerprint IS NULL

UPDATE idempotent_record
SET status = 1, biz_id = #{bizId}
WHERE idempotent_key = #{idempotentKey}
  AND user_id = #{userId}
  AND request_fingerprint = #{requestFingerprint}
  AND status = 0
